package validator

import (
	"context"

	"github.com/nats-io/nats.go"
	"google.golang.org/protobuf/proto"
	"xiam.li/protonats/go/protonats"
)

// Validator interface matches the method signature generated by
// protoc-gen-validate or your custom validation logic.
type Validator interface {
	Validate() error
}

// NewServerInterceptor returns a server interceptor that validates incoming requests.
// If the request message implements the Validator interface, its Validate method is called.
// If validation fails, an error with code ErrValidationFailed is returned to the client.
func NewServerInterceptor() protonats.UnaryServerInterceptor {
	return func(ctx context.Context, req proto.Message, info *protonats.MethodInfo, next protonats.UnaryHandler) (proto.Message, error) {
		if v, ok := req.(Validator); ok {
			if err := v.Validate(); err != nil {
				return nil, protonats.WrapServerErr(err, protonats.ErrValidationFailed.Code(), protonats.ErrValidationFailed.String())
			}
		}
		return next(ctx, req)
	}
}

// NewClientInterceptor returns a client interceptor that validates outgoing requests.
// If the request message implements the Validator interface, its Validate method is called.
// If validation fails, an error with code ErrValidationFailed is returned.
//
// This prevents invalid requests from being sent to the server, but does not guarantee
// that the server will accept the request, as server-side validation may still fail.
// The server should always perform its own validation and not rely solely on client-side validation.
func NewClientInterceptor() protonats.UnaryClientInterceptor {
	return func(ctx context.Context, info *protonats.MethodInfo, req, reply proto.Message, headers nats.Header, next protonats.UnaryInvoker, callOpts ...protonats.CallOption) error {
		if v, ok := req.(Validator); ok {
			if err := v.Validate(); err != nil {
				return protonats.ServiceError{Code: protonats.ErrValidationFailed.Code(), Description: protonats.ErrValidationFailed.String(), Details: err.Error()}
			}
		}
		return next(ctx, info, req, reply, headers, callOpts...)
	}
}
